export const authenticate: Koa.Middleware = async (ctx, next) => {
  const token = ctx.get('Authorization').replace('Bearer ', '');
  try {
    ctx.state.user = jwt.verify(token, process.env.JWT_SECRET!, {
      algorithms: ['HS256'],
      ignoreExpiration: true,
    });
  } catch {
    ctx.throw(401);
  }
  await next();
};

